using System.Text.Json;
namespace AlphaQuantum.ShadowAITools;
public sealed class ApiException(string message,int statusCode,string body):Exception(message){public int StatusCode{get;}=statusCode;public string Body{get;}=body;}
public sealed class ShadowAIToolsClient{private readonly string _apiKey,_baseUrl;private readonly HttpClient _http;public ShadowAIToolsClient(string apiKey,HttpClient? httpClient=null,string baseUrl="https://www.aitoolsblocklist.com/api"){if(string.IsNullOrWhiteSpace(apiKey))throw new ArgumentException("API key is required",nameof(apiKey));_apiKey=apiKey;_http=httpClient??new HttpClient{Timeout=TimeSpan.FromSeconds(30)};_baseUrl=baseUrl.TrimEnd('/');}
private async Task<Dictionary<string,JsonElement>> LookupAsync(string value,CancellationToken cancellationToken=default){if(string.IsNullOrWhiteSpace(value))throw new ArgumentException("Input is required",nameof(value));var uri = new Uri($"{_baseUrl}/check?domain={Uri.EscapeDataString(value)}"); using var request = new HttpRequestMessage(HttpMethod.Get, uri); request.Headers.Add("X-API-Key", _apiKey);request.Headers.Accept.ParseAdd("application/json");using var response=await _http.SendAsync(request,cancellationToken);var body=await response.Content.ReadAsStringAsync(cancellationToken);if(!response.IsSuccessStatusCode)throw new ApiException("API request failed",(int)response.StatusCode,body);return JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(body)??new();}
public Task<Dictionary<string,JsonElement>> CheckAsync(string value,CancellationToken cancellationToken=default)=>LookupAsync(value,cancellationToken);
public async Task<IReadOnlyList<Dictionary<string,JsonElement>>> ScanAsync(string path,CancellationToken cancellationToken=default){var hosts=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var line in await File.ReadAllLinesAsync(path,cancellationToken)){foreach(var token in line.Split(new[]{' ', '\t', ',', ';'},StringSplitOptions.RemoveEmptyEntries)){var candidate=token.Contains("://",StringComparison.Ordinal)?token:"https://"+token;if(Uri.TryCreate(candidate,UriKind.Absolute,out var parsed)&&parsed.Host.Contains('.'))hosts.Add(parsed.Host);}}var results=new List<Dictionary<string,JsonElement>>();foreach(var host in hosts)results.Add(await CheckAsync(host,cancellationToken));return results;}
}
